package predict4s
package sgp

import org.scalatest.funsuite.AnyFunSuite
import predict4s.coord.SGP72Constants
import predict4s.coord.TLE
import predict4s.sgp.ref.SGP4Vallado
import scala.io.Source

/** Cross-checks the SGP4Vallado propagation against the reference values computed with the python3-sgp4 library
  * (Vallado's reference implementation).
  *
  * The reference CSV is generated by scripts/gen-python-sgp4-reference.py from the TLEs and time grids in nearTLEs.txt.
  * Positions are compared in km and velocities in km/s, both in the TEME frame.
  */
class PythonSgp4CrossCheck extends AnyFunSuite {

  import spire.std.any.DoubleAlgebra
  implicit val wgs: SGP72Constants[Double] = SGP72Constants.tleDoubleConstants

  case class TleWithGrid(tle: TLE, line1: String, line2: String, start: Double, end: Double, step: Double) {
    def times: Seq[Double] = {
      val count = math.round((end - start) / step).toInt + 1
      (0 until count).map(i => start + step * i)
    }
  }

  def readTles: List[TleWithGrid] = {
    val lines = Source.fromInputStream(getClass.getResourceAsStream("/nearTLEs.txt")).getLines().toList
    val tles = scala.collection.mutable.ListBuffer[TleWithGrid]()
    val iter = lines.iterator
    while (iter.hasNext) {
      val line1 = iter.next()
      if (!line1.startsWith("#") && line1.trim.nonEmpty) {
        val line2 = iter.next()
        val grid = line2.trim.split("\\s+").takeRight(3).map(_.toDouble)
        require(grid.length == 3, s"expected start, end, step at the end of TLE line 2: $line2")
        val (start, end, step) = (grid(0), grid(1), grid(2))
        tles += TleWithGrid(TLE.parseLines(List(line1, line2)).head, line1, line2, start, end, step)
      }
    }
    tles.toList
  }

  def readReference: Map[(Int, Double), (Double, Double, Double, Double, Double, Double)] = {
    val rows = Source.fromInputStream(getClass.getResourceAsStream("/pythonSgp4Reference.csv")).getLines()
    rows
      .drop(1)
      .map { row =>
        val cols = row.split(",").map(_.toDouble)
        ((cols(0).toInt, cols(1)), (cols(2), cols(3), cols(4), cols(5), cols(6), cols(7)))
      }
      .toMap
  }

  val reference = readReference

  for (tleWithGrid <- readTles) {
    val satnum = tleWithGrid.tle.satelliteNumber
    val vasgp4 = SGP4Vallado.fromTLE(tleWithGrid.tle, wgs).get
    for (t <- tleWithGrid.times) {
      reference.get((satnum, t)) match {
        case None                              => // python3-sgp4 reported an error for this time, skip
        case Some((ex, ey, ez, evx, evy, evz)) =>
          test(s"python3-sgp4 cross-check for TLE $satnum at time $t minutes") {
            val pv = vasgp4.propagate(t) match {
              case org.scalactic.Good((pv, _, _)) => pv
              case org.scalactic.Bad(msg)         => fail(s"propagation failed: $msg")
            }
            def assertClose(actual: Double, expected: Double, tol: Double, what: String): Unit =
              assert(math.abs(actual - expected) < tol, s"$what: $actual vs $expected (tolerance $tol)")
            assertClose(pv.x, ex, 1.0e-5, "x")
            assertClose(pv.y, ey, 1.0e-5, "y")
            assertClose(pv.z, ez, 1.0e-5, "z")
            assertClose(pv.vx, evx, 1.0e-8, "vx")
            assertClose(pv.vy, evy, 1.0e-8, "vy")
            assertClose(pv.vz, evz, 1.0e-8, "vz")
          }
      }
    }
  }
}
